// Lier, Disciple of the Drowned
// status: ready
// Spells can't be countered.
// Each instant and sorcery card in your graveyard has flashback. The flashback cost is equal to that card's mana cost.
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_0_affects(q: &dyn LayerQuery, source: ObjectId, affected: ObjectId, so_far: &Chars) -> bool { let asker = &Asker::new(source, q.controller(source)); (q.state().obj(affected).became.is_none() && q.state().obj(affected).zone.kind() == ZoneKind::Stack) && true }
#[allow(unused_variables)] fn ability_0_apply_0(q: &dyn LayerQuery, source: ObjectId, chars: &mut Chars) { let asker = &Asker::new(source, q.controller(source)); chars.keywords = chars.keywords.with(Keyword::CantBeCountered); }
#[allow(unused_variables)] fn ability_1_cost(q: &dyn Query, asker: &Asker, card: ObjectId, player: PlayerId) -> Option<Cost> { (player == asker.controller && (q.card(q.obj(card).card).is(CardType::Instant) || q.card(q.obj(card).card).is(CardType::Sorcery)) && q.card(q.chars(card).card).has_cost).then(|| Cost::mana(q.card(q.chars(card).card).cost)) }

